prompts.raw:
function ({ vars }) {
  const system = vars.customPrompt
    ? `${AUTHORING_SYSTEM_PROMPT}\n\n---\n\n${vars.customPrompt}`
    : AUTHORING_SYSTEM_PROMPT;
  return [
    { role: 'system', content: `{% raw %}${system}{% endraw %}` },
    { role: 'user', content: `{% raw %}${vars.request}{% endraw %}` },
  ];
}
